#include <vector>
#include <fstream>
#include <string>
#include <algorithm>
#define main original_daphne_main
#include "../daphne-cuda/main.cu"
#undef main
int main(){const int n=100000,r=20;uint64_t s=20260722;std::vector<float>cp(n*8,0),expected(n*4),got(n*4);std::vector<int>valid(n);for(int i=0;i<n;i++){float u[4];for(int j=0;j<4;j++){s=s*6364136223846793005ull+1442695040888963407ull;u[j]=float((s>>33)&0x7fffffff)/float(0x7fffffff);}cp[i*8]=(u[0]-.5f)*2;cp[i*8+1]=(u[1]-.5f)*2;cp[i*8+2]=(i+1)%5==0?-1.f:u[2]*10+15;cp[i*8+4]=u[3];int v;project_point(cp[i*8],cp[i*8+1],cp[i*8+2],expected[i],expected[n+i],expected[2*n+i],v);expected[3*n+i]=float(v);}
float *dcp,*x,*y,*z;int*v;cudaMalloc(&dcp,n*8*4);cudaMalloc(&x,n*4);cudaMalloc(&y,n*4);cudaMalloc(&z,n*4);cudaMalloc(&v,n*4);cudaMemcpy(dcp,cp.data(),n*8*4,cudaMemcpyHostToDevice);auto launch=[&](){project_kernel<<<(n+255)/256,256>>>(dcp,x,y,z,v,n);};launch();cudaDeviceSynchronize();bool all=true;for(int trial=1;trial<=5;trial++){auto start=std::chrono::steady_clock::now();for(int j=0;j<r;j++)launch();auto error=cudaDeviceSynchronize();double secs=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/r;cudaMemcpy(got.data(),x,n*4,cudaMemcpyDeviceToHost);cudaMemcpy(got.data()+n,y,n*4,cudaMemcpyDeviceToHost);cudaMemcpy(got.data()+2*n,z,n*4,cudaMemcpyDeviceToHost);cudaMemcpy(valid.data(),v,n*4,cudaMemcpyDeviceToHost);for(int i=0;i<n;i++)got[3*n+i]=float(valid[i]);bool ok=error==cudaSuccess;double maxabs=0;for(int i=0;i<n*4;i++){double diff=std::abs(double(got[i])-expected[i]);ok &=std::isfinite(got[i])&&diff<=1e-3;maxabs=std::max(maxabs,diff);}all &=ok;std::string path=std::string(getenv("STUDY_OUTPUT_DIR"))+"/output_trial"+std::to_string(trial)+".bin";std::ofstream(path,std::ios::binary).write((char*)got.data(),n*4*4);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%d,\"max_abs_error\":%.12g,\"max_rel_error\":0,\"timing_region\":\"kernel_launch_loop_per_internal_repeat\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%d,\"byte_order\":\"little\"}}\n",trial,secs,ok?"true":"false",n*4,maxabs,r,path.c_str(),n*4);}puts(all?"PASS":"FAIL");return all?0:1;}
